#!/bin/bash
# Uninstall script for Memory Tracker by Timely
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Memory Tracker by Timely..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Memory Tracker by Timely if running..."
pkill -f "Memory Tracker by Timely" 2>/dev/null || true

# Remove /Applications/Memory.app
echo "Removing /Applications/Memory.app..."
if [ -d "/Applications/Memory.app" ]; then
    rm -rf "/Applications/Memory.app" 2>/dev/null || true
elif [ -f "/Applications/Memory.app" ]; then
    rm -f "/Applications/Memory.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Memory
echo "Removing $HOME/Library/Application Support/Memory..."
if [ -d "$HOME/Library/Application Support/Memory" ]; then
    rm -rf "$HOME/Library/Application Support/Memory" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Memory" ]; then
    rm -f "$HOME/Library/Application Support/Memory" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/com.timeapp.devlpmp.Timely-Mac-Tracker
echo "Removing $HOME/Library/Caches/com.timeapp.devlpmp.Timely-Mac-Tracker..."
if [ -d "$HOME/Library/Caches/com.timeapp.devlpmp.Timely-Mac-Tracker" ]; then
    rm -rf "$HOME/Library/Caches/com.timeapp.devlpmp.Timely-Mac-Tracker" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.timeapp.devlpmp.Timely-Mac-Tracker" ]; then
    rm -f "$HOME/Library/Caches/com.timeapp.devlpmp.Timely-Mac-Tracker" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Memory
echo "Removing $HOME/Library/Logs/Memory..."
if [ -d "$HOME/Library/Logs/Memory" ]; then
    rm -rf "$HOME/Library/Logs/Memory" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Memory" ]; then
    rm -f "$HOME/Library/Logs/Memory" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.timeapp.devlpmp.Timely-Mac-Tracker.plist
echo "Removing $HOME/Library/Preferences/com.timeapp.devlpmp.Timely-Mac-Tracker.plist..."
if [ -d "$HOME/Library/Preferences/com.timeapp.devlpmp.Timely-Mac-Tracker.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.timeapp.devlpmp.Timely-Mac-Tracker.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.timeapp.devlpmp.Timely-Mac-Tracker.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.timeapp.devlpmp.Timely-Mac-Tracker.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
